import React, { useContext } from 'react';
import { useNavigate } from 'react-router-dom';
import { AppContext } from './AppContext';
import personIcon from '../assets/person.png';
import exitIcon from '../assets/exit.png';
import './SettingsPanel.css';

export default function SettingsPanel() {
  const { user, theme, setTheme, language, setLanguage } = useContext(AppContext);
  const navigate = useNavigate();

  const toggleTheme = () => {
    setTheme(theme === 'dark' ? 'light' : 'dark');
  };

  const handleLanguageChange = (e) => {
    setLanguage(e.target.value);
  };

  return (
    <div className={`settings-panel ${theme === 'dark' ? 'dark' : ''}`}>
      {/* Back button top-right */}
      <button
        className="back-button"
        onClick={() => navigate('/landing')}
        aria-label="Back to Landing Page"
        title="Back to Home"
      >
        <img src={exitIcon} alt="Back" />
      </button>

      {/* User avatar and info */}
      <div className="user-header">
        <img src={personIcon} alt="User Avatar" className="avatar" />
        <div className="user-info">
          <h2>{user?.full_name || 'User'}</h2>
          <p className="email">{user?.email || 'No email provided'}</p>
          <p className="id"><strong>ID:</strong> {user?.id || 'N/A'}</p>
        </div>
      </div>

      {/* Settings controls */}
      <div className="setting-group">
        <label>Theme</label>
        <button onClick={toggleTheme} className="theme-toggle-btn">
          Switch to {theme === 'dark' ? 'Light' : 'Dark'} Mode
        </button>
      </div>

      <div className="setting-group">
        <label>Language</label>
        <select value={language} onChange={handleLanguageChange}>
          <option value="en">English</option>
          <option value="fr">French</option>
          <option value="ar">Arabic</option>
        </select>
      </div>
    </div>
  );
}
